head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > mandatory]<br/>validate() 메소드로 컴포넌트의 입력값 유효성 체크 시 입력값의 유/무를 확인하도록 설정합니다.",
    "validation" : [
        "validate() 메소드 실행 시 입력값 유/무에 대한 유효성 체크를 수행합니다.",
        "미설정 시 컴포넌트의 입력값 유/무를 확인하지 않습니다. (기본값 false)",
        "true 설정 시 컴포넌트의 입력값 유/무를 확인합니다.",
        "true 설정 시 'w2searchbox_mandatory' 클래스가 적용됩니다.",
        "false 설정 시 컴포넌트의 입력값 유/무를 확인하지 않습니다.",
        "유효성 체크 실패 시 displaymessage 설정에 따라 실패 메시지가 출력됩니다.",
        "기본 실패 메시지는 '필수 입력 항목입니다.' 이며 invalidMessage / invalidMessageFunc 속성으로 변경할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}


// target1 (mandatory 미설정 → 기본값 false 동작 / 빈 입력값 + validate → PASS)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}

scwin.btn_getClass1_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1 className : " + target1.render.className);
};


// target2 (mandatory=true / 빈 입력값 + validate → FAIL, 기본 메시지 alert)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}

scwin.btn_getClass2_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target2 className : " + target2.render.className);
};


// target3 (mandatory=true / 입력값 있음 + validate → PASS)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("가나다");
};

scwin.btn_validate3_onclick = function (e) {
    scwin.btn_setValue3_onclick();
    scwin.check_validate(target3);
}


// target4 (mandatory=false / 빈 입력값 + validate → PASS)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("");
};

scwin.btn_validate4_onclick = function (e) {
    scwin.btn_setValue4_onclick();
    scwin.check_validate(target4);
}

scwin.btn_getClass4_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target4 className : " + target4.render.className);
};


// target5 (mandatory=true / invalidMessage 설정 / 빈 입력값 + validate → FAIL, 사용자 정의 메시지 alert)
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("");
};

scwin.btn_validate5_onclick = function (e) {
    scwin.btn_setValue5_onclick();
    scwin.check_validate(target5);
}
